// Authored Yogabase password and external sign-in test. This file is not generated by Microsoft Kiota.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import test from "node:test";
import { FetchRequestAdapter, HttpClient } from "@microsoft/kiota-http-fetchlibrary";
import { createYogabaseApiClient, YogabaseAuthError, YogabaseExternalSignIn, YogabaseSession } from "../dist/index.js";

const GATEWAY = "https://apps.example.test";
const REDIRECT = "com.yogabase.app:/oauth/callback";
const IDENTITY = "yogabase.project.identity";
const PROJECT = "11111111-1111-4111-8111-111111111111";
const TOKENS = { access_token: "access-1", token_type: "Bearer", expires_in: 3600, refresh_token: "refresh-1" };

const json = (body, status = 200, headers = []) => new Response(JSON.stringify(body), { status, headers: [["Content-Type", "application/json"], ...headers] });
const refusal = (status, code) => json({ title: code, status, code, traceId: "trace-1" }, status);
const found = location => new Response(null, { status: 302, headers: { Location: location } });
const signedIn = () => new Response(null, { status: 204, headers: [["Set-Cookie", `${IDENTITY}=signed-in; path=/; httponly`]] });

// The gateway's sign-in routes on a fake fetch, recording every call. A route can be replaced; the default
// authorize answers as the product does: a 302 with the code and state, or 401 unless the identity cookie came back.
function gateway(routes = {}) {
    const calls = [];
    const handlers = {
        "/v1/client-config/sy_pub_test": () => json({
            projectId: PROJECT, oidcPublicClientId: "native", oidcRedirectUris: [REDIRECT, "other:/x"],
            oidcScopes: ["openid", "offline_access"], oidcDiscoveryEndpoint: `${GATEWAY}/.well-known/openid-configuration`,
        }),
        "/.well-known/openid-configuration": () => json({ authorization_endpoint: `${GATEWAY}/connect/authorize`, token_endpoint: `${GATEWAY}/connect/token` }),
        "/auth/login": signedIn,
        "/auth/mfa/verify": () => new Response(null, { status: 204, headers: [["Set-Cookie", `${IDENTITY}=signed-in; path=/`], ["Set-Cookie", "tfa=; expires=Thu, 01 Jan 1970 00:00:00 GMT"]] }),
        "/connect/authorize": call => call.cookie?.includes(`${IDENTITY}=signed-in`)
            ? found(`${REDIRECT}?code=code-1&state=${call.query.get("state")}`)
            : refusal(401, "interactive_login_required"),
        "/connect/token": () => json(TOKENS),
        "/auth/external/google/start": () => json({ authorizationUrl: "https://accounts.example.test/auth?x=1", state: "gw-state" }),
        "/auth/external/google/callback": signedIn,
        ...routes,
    };
    const fetcher = async (url, init = {}) => {
        const { pathname, searchParams } = new URL(url);
        const headers = new Headers(init.headers);
        const call = { path: pathname, query: searchParams, body: String(init.body ?? ""), cookie: headers.get("Cookie"), authorization: headers.get("Authorization"), redirect: init.redirect };
        calls.push(call);
        return handlers[pathname](call);
    };
    const session = new YogabaseSession({ gatewayHost: GATEWAY, publishableKey: "sy_pub_test", fetch: fetcher });
    return { calls, session, paths: () => calls.map(call => call.path) };
}

const signIn = session => session.signInWithPassword("user@example.com", "pw");
const refusedWith = (status, code) => error => error instanceof YogabaseAuthError && error.status === status && error.code === code;

test("sign-in logs in, authorizes with the cookie and an S256 challenge, and keeps the tokens", async () => {
    const { calls, paths, session } = gateway();
    await signIn(session);

    assert.deepEqual(paths(), ["/v1/client-config/sy_pub_test", "/.well-known/openid-configuration", "/auth/login", "/connect/authorize", "/connect/token"]);
    const [, , login, authorize, token] = calls;
    assert.deepEqual(JSON.parse(login.body), { email: "user@example.com", password: "pw" });
    assert.deepEqual([authorize.cookie, authorize.redirect], [`${IDENTITY}=signed-in`, "manual"]);
    const form = new URLSearchParams(token.body);
    assert.deepEqual(
        ["grant_type", "client_id", "code", "redirect_uri"].map(name => form.get(name)),
        ["authorization_code", "native", "code-1", REDIRECT],
    );
    const verifier = form.get("code_verifier");
    assert.ok(verifier.length >= 43);
    assert.deepEqual(
        ["response_type", "client_id", "redirect_uri", "scope", "code_challenge_method"].map(name => authorize.query.get(name)),
        ["code", "native", REDIRECT, "openid offline_access", "S256"],
    );
    assert.equal(authorize.query.get("code_challenge"), createHash("sha256").update(verifier, "ascii").digest("base64url"));
    assert.ok(!authorize.query.toString().includes(verifier), "the verifier is sent only to the token endpoint");
    assert.equal(await session.accessToken(), "access-1");
    assert.equal(session.projectId, PROJECT);
});

test("the generated client sends the stored token to the gateway and to no other origin", async () => {
    const { session } = gateway();
    await signIn(session);
    const sent = [];
    const fakeFetch = async (url, init) => {
        sent.push([String(url), new Headers(init.headers).get("Authorization")]);
        return json([]);
    };
    const adapter = new FetchRequestAdapter(session, undefined, undefined, new HttpClient(fakeFetch));
    adapter.baseUrl = GATEWAY;
    await createYogabaseApiClient(adapter).v1.servers.get();
    adapter.baseUrl = "https://elsewhere.example.test";
    await createYogabaseApiClient(adapter).v1.servers.get();

    assert.deepEqual(sent, [[`${GATEWAY}/v1/servers`, "Bearer access-1"], ["https://elsewhere.example.test/v1/servers", null]]);
});

test("a login refusal carries the gateway's code and ends the call before the authorize step", async () => {
    for (const [status, code] of [[401, "invalid_credentials"], [403, "mfa_enrollment_required"], [429, "authentication_rate_limited"]]) {
        const { paths, session } = gateway({ "/auth/login": () => refusal(status, code) });
        await assert.rejects(session.signInWithPassword("user@example.com", "wrong"), error => refusedWith(status, code)(error) && error.correlationId === "trace-1", code);
        assert.equal(paths().at(-1), "/auth/login");
        await assert.rejects(session.accessToken(), refusedWith(401, "authentication_required"));
    }
});

test("a login that set no cookie ends at the authorize step and requests no token", async () => {
    const { paths, session } = gateway({ "/auth/login": () => new Response(null, { status: 204 }) });
    await assert.rejects(signIn(session), refusedWith(401, "interactive_login_required"));
    assert.deepEqual(paths().slice(2), ["/auth/login", "/connect/authorize"]);
});

test("a redirect with another state, no code, an error or another redirect URI requests no token", async () => {
    const cases = [
        ["authorization_response_invalid", () => `${REDIRECT}?code=code-1&state=forged`],
        ["authorization_response_invalid", state => `${REDIRECT}?state=${state}`],
        ["access_denied", state => `${REDIRECT}?error=access_denied&state=${state}`],
        ["authorization_redirect_mismatch", state => `https://other.example.test/cb?code=code-1&state=${state}`],
        ["authorization_redirect_mismatch", state => `com.yogabase.app:/elsewhere?code=code-1&state=${state}`],
    ];
    for (const [code, location] of cases) {
        const { paths, session } = gateway({ "/connect/authorize": call => found(location(call.query.get("state"))) });
        await assert.rejects(signIn(session), refusedWith(400, code), code);
        assert.ok(!paths().includes("/connect/token"), code);
        await assert.rejects(session.accessToken(), refusedWith(401, "authentication_required"));
    }
});

test("a discovery document naming another origin is refused before the password is sent", async () => {
    const { paths, session } = gateway({ "/.well-known/openid-configuration": () => json({ authorization_endpoint: "https://evil.example.test/connect/authorize", token_endpoint: `${GATEWAY}/connect/token` }) });
    await assert.rejects(signIn(session), refusedWith(502, "oidc_discovery_invalid"));
    assert.ok(!paths().includes("/auth/login"));
});

test("an account with MFA is reported by name, and finishes when the authenticator code is passed", async () => {
    const challenge = () => json({ status: 202, code: "mfa_required" }, 202, [["Set-Cookie", "tfa=challenge; path=/"]]);
    const { calls, paths, session } = gateway({ "/auth/login": challenge });
    await assert.rejects(signIn(session), refusedWith(202, "mfa_required"));
    assert.ok(!paths().includes("/auth/mfa/verify") && !paths().includes("/connect/token"));

    calls.length = 0;
    await session.signInWithPassword("user@example.com", "pw", "123456");
    const verify = calls.find(call => call.path === "/auth/mfa/verify");
    assert.deepEqual([JSON.parse(verify.body), verify.cookie], [{ code: "123456" }, "tfa=challenge"]);
    assert.equal(calls.find(call => call.path === "/connect/authorize").cookie, `${IDENTITY}=signed-in`);
    assert.equal(await session.accessToken(), "access-1");
});

test("an expiring token is refreshed once for concurrent callers, and the refresh token rotates", async () => {
    let issued = 0;
    const { calls, session } = gateway({
        "/connect/token": () => {
            issued += 1;
            return json({ ...TOKENS, access_token: `access-${issued}`, refresh_token: `refresh-${issued}`, expires_in: issued === 1 ? 30 : 3600 });
        },
    });
    await signIn(session);
    assert.deepEqual(await Promise.all([session.accessToken(), session.accessToken(), session.accessToken()]), ["access-2", "access-2", "access-2"]);
    assert.equal(await session.accessToken(), "access-2");

    const requests = calls.filter(call => call.path === "/connect/token").map(call => new URLSearchParams(call.body));
    assert.equal(requests.length, 2);
    assert.deepEqual(["grant_type", "client_id", "refresh_token"].map(name => requests[1].get(name)), ["refresh_token", "native", "refresh-1"]);
});

test("a token refusal is named by its OAuth error, and the host and key are checked up front", async () => {
    const { session } = gateway({ "/connect/token": () => json({ error: "invalid_grant" }, 400) });
    await assert.rejects(signIn(session), refusedWith(400, "invalid_grant"));
    assert.throws(() => new YogabaseSession({ gatewayHost: "http://apps.example.test", publishableKey: "sy_pub_test" }), TypeError);
    assert.throws(() => new YogabaseSession({ gatewayHost: GATEWAY, publishableKey: "" }), TypeError);
});

test("external sign-in sends only the S256 challenge to start, the verifier to the callback, and keeps the tokens", async () => {
    const { calls, paths, session } = gateway();
    const pending = await session.startExternalSignIn("google", REDIRECT);
    assert.equal(pending.authorizationUrl, "https://accounts.example.test/auth?x=1");
    await session.completeExternalSignIn(pending, `${REDIRECT}?code=ext-code&state=gw-state`);

    assert.deepEqual(paths(), ["/auth/external/google/start", "/v1/client-config/sy_pub_test", "/.well-known/openid-configuration",
        "/auth/external/google/callback", "/connect/authorize", "/connect/token"]);
    const [start, , , callback, authorize] = calls;
    const { codeVerifier, ...rest } = JSON.parse(callback.body);
    assert.deepEqual(rest, { code: "ext-code", state: "gw-state" });
    assert.match(codeVerifier, /^[A-Za-z0-9_-]{43,128}$/);
    assert.deepEqual(JSON.parse(start.body), { redirectUri: REDIRECT, codeChallenge: createHash("sha256").update(codeVerifier, "ascii").digest("base64url") });
    assert.ok(!start.body.includes(codeVerifier), "the verifier is sent only to the callback");
    assert.deepEqual([start.authorization, callback.authorization, callback.redirect], [null, null, "manual"]);
    assert.equal(authorize.cookie, `${IDENTITY}=signed-in`);
    assert.equal(await session.accessToken(), "access-1");
    assert.equal(session.projectId, PROJECT);
});

test("a redirect with another state, an error, no code, a repeated parameter or another address makes no callback request", async () => {
    const cases = [
        ["authorization_response_invalid", `${REDIRECT}?code=c&state=forged`],
        ["authorization_response_invalid", `${REDIRECT}?error=access_denied&state=forged`],
        ["authorization_response_invalid", `${REDIRECT}?code=c&code=d&state=gw-state`],
        ["authorization_response_invalid", `${REDIRECT}?state=gw-state`],
        ["access_denied", `${REDIRECT}?error=access_denied&state=gw-state`],
        ["authorization_redirect_mismatch", "https://other.example.test/oauth/callback?code=c&state=gw-state"],
        ["authorization_redirect_mismatch", "com.yogabase.app:/elsewhere?code=c&state=gw-state"],
        ["authorization_redirect_mismatch", `${REDIRECT}?code=c&state=gw-state#fragment`],
    ];
    for (const [code, redirect] of cases) {
        const { calls, session } = gateway();
        const pending = await session.startExternalSignIn("google", REDIRECT);
        await assert.rejects(session.completeExternalSignIn(pending, redirect), refusedWith(400, code), redirect);
        assert.equal(calls.length, 1, redirect);   // the start alone
        await assert.rejects(session.accessToken(), refusedWith(401, "authentication_required"));
    }
});

test("a pending sign-in completes only the redirect of its own start", async () => {
    let issued = 0;
    const { calls, session } = gateway({ "/auth/external/google/start": () => json({ authorizationUrl: "https://accounts.example.test/auth", state: `state-${++issued}` }) });
    const first = await session.startExternalSignIn("google", REDIRECT);
    const second = await session.startExternalSignIn("google", REDIRECT);
    const redirect = `${REDIRECT}?code=c&state=state-2`;
    await assert.rejects(session.completeExternalSignIn(first, redirect), refusedWith(400, "authorization_response_invalid"));
    await assert.rejects(session.completeExternalSignIn(new YogabaseExternalSignIn("https://accounts.example.test/auth"), redirect), TypeError);
    assert.equal(calls.length, 2);   // both starts, nothing after
    await session.completeExternalSignIn(second, redirect);
    assert.equal(await session.accessToken(), "access-1");
});

test("a callback refusal carries the gateway's code and requests no token; a discovery on another origin sends no code", async () => {
    for (const [status, code] of [[401, "external_identity_invalid"], [409, "external_identity_email_in_use"], [403, "external_email_unverified"], [400, "external_callback_invalid"]]) {
        const { paths, session } = gateway({ "/auth/external/google/callback": () => refusal(status, code) });
        const pending = await session.startExternalSignIn("google", REDIRECT);
        await assert.rejects(session.completeExternalSignIn(pending, `${REDIRECT}?code=c&state=gw-state`), error => refusedWith(status, code)(error) && error.correlationId === "trace-1", code);
        assert.ok(!paths().includes("/connect/authorize"), code);
        await assert.rejects(session.accessToken(), refusedWith(401, "authentication_required"));
    }
    const { paths, session } = gateway({ "/.well-known/openid-configuration": () => json({ authorization_endpoint: "https://evil.example.test/connect/authorize", token_endpoint: `${GATEWAY}/connect/token` }) });
    const pending = await session.startExternalSignIn("google", REDIRECT);
    await assert.rejects(session.completeExternalSignIn(pending, `${REDIRECT}?code=c&state=gw-state`), refusedWith(502, "oidc_discovery_invalid"));
    assert.ok(!paths().includes("/auth/external/google/callback"));
});

test("a start refusal carries the gateway's code, and an answer without an https address and a state is refused", async () => {
    for (const [status, code] of [[400, "external_redirect_uri_invalid"], [404, "external_provider_unknown"], [503, "external_provider_unavailable"]]) {
        const { session } = gateway({ "/auth/external/google/start": () => refusal(status, code) });
        await assert.rejects(session.startExternalSignIn("google", REDIRECT), refusedWith(status, code), code);
    }
    for (const answer of [{ authorizationUrl: "http://accounts.example.test/auth", state: "s" }, { authorizationUrl: "https://accounts.example.test/auth", state: "" }, { state: "s" }]) {
        const { session } = gateway({ "/auth/external/google/start": () => json(answer) });
        await assert.rejects(session.startExternalSignIn("google", REDIRECT), refusedWith(502, "external_start_invalid"));
    }
    const { calls, session } = gateway();
    await assert.rejects(session.startExternalSignIn("google/../x", REDIRECT), TypeError);
    assert.equal(calls.length, 0);
});

test("a callback that needs MFA is reported by name and finishes with the code, without the callback sent again", async () => {
    const { calls, paths, session } = gateway({ "/auth/external/google/callback": () => json({ status: 202, code: "mfa_required" }, 202, [["Set-Cookie", "tfa=challenge; path=/"]]) });
    const pending = await session.startExternalSignIn("google", REDIRECT);
    const redirect = `${REDIRECT}?code=c&state=gw-state`;
    await assert.rejects(session.completeExternalSignIn(pending, redirect), refusedWith(202, "mfa_required"));
    assert.ok(!paths().includes("/auth/mfa/verify") && !paths().includes("/connect/token"));

    await session.completeExternalSignIn(pending, redirect, "123456");
    assert.equal(paths().filter(path => path.endsWith("/callback")).length, 1);
    const verify = calls.find(call => call.path === "/auth/mfa/verify");
    assert.deepEqual([JSON.parse(verify.body), verify.cookie], [{ code: "123456" }, "tfa=challenge"]);
    assert.equal(calls.find(call => call.path === "/connect/authorize").cookie, `${IDENTITY}=signed-in`);
    assert.equal(await session.accessToken(), "access-1");
});
